def build_candidate(output: Path) -> Path:
    output.parent.mkdir(parents=True, exist_ok=True)
    build_v14_public(output)
    html = output.read_text(encoding="utf-8")
    html = html.replace("</head>", CSS + "\n</head>", 1)
    html = html.replace("</body>", SCRIPT + "\n</body>", 1)
    required = (
        'id="lab14-engagement-excellence-style"',
        'id="lab14-engagement-excellence-runtime"',
        'Lab14EngagementExperience',
        'SIMULATED WORLD',
        'Runtime Sandbox',
    )
    missing = [marker for marker in required if marker not in html]
    if missing:
        raise RuntimeError(f"Lab 14 engagement candidate incomplete: {missing}")
    for token in ("<script src=", "fetch(", "XMLHttpRequest", "WebSocket(", "EventSource("):
        if token in html:
            raise RuntimeError(f"Lab 14 engagement candidate violates one-file/offline boundary: {token}")
    output.write_text(html, encoding="utf-8")
    return output


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    output = args.output if args.output.is_absolute() else ROOT / args.output
    result = build_candidate(output)
    print(f"Built Lab 14 engagement candidate: {result}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
